const std = @import("std"); const net = std.Io.net; const mem = std.mem;
const CF = .{ .guid = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11", .bufz = 16384, .maxm = 32 << 20, .evmx = 4000, .tick = 25, .evby = 64 << 20 };
pub const Conn = struct { gpaz: std.mem.Allocator, iozz: std.Io, strm: net.Stream, rdr: net.Stream.Reader, wrt: net.Stream.Writer, rbuf: []u8, wbuf: []u8, dead: std.atomic.Value(i64) = .init(0), tout: std.atomic.Value(bool) = .init(false), stop: std.atomic.Value(bool) = .init(false), thrd: ?std.Thread = null, nid: u32 = 1, evts: std.ArrayList([]u8) = .empty, evby: usize = 0, evdr: usize = 0,
pub fn armz(self: *Conn, mill: u32) void { if (mill == 0) { self.dead.store(0, .release); return; } self.tout.store(false, .release); self.dead.store(nowMs(self.iozz) + mill, .release); }
pub fn sendRaw(self: *Conn, opc: u8, payload: []const u8) !void { var hdr: [14]u8 = undefined; hdr[0] = 0x80 | opc; var cnt: usize = 2; if (payload.len < 126) { hdr[1] = 0x80 | @as(u8, @intCast(payload.len)); } else if (payload.len < 65536) { hdr[1] = 0x80 | 126; mem.writeInt(u16, hdr[2..4], @intCast(payload.len), .big); cnt = 4; } else { hdr[1] = 0x80 | 127; mem.writeInt(u64, hdr[2..10], payload.len, .big); cnt = 10; } var key: [4]u8 = undefined; self.iozz.random(&key); @memcpy(hdr[cnt .. cnt + 4], &key); cnt += 4; const wr = &self.wrt.interface; wr.writeAll(hdr[0..cnt]) catch return self.fail(); var chk: [4096]u8 = undefined; var pos: usize = 0; while (pos < payload.len) { const lenz = @min(chk.len, payload.len - pos); for (payload[pos .. pos + lenz], 0..) |byt, idx| chk[idx] = byt ^ key[(pos + idx) % 4]; wr.writeAll(chk[0..lenz]) catch return self.fail(); pos += lenz; } wr.flush() catch return self.fail(); }
fn fail(self: *Conn) anyerror { return if (self.tout.load(.acquire)) error.Timeout else error.Closed; }
pub fn readMsg(self: *Conn, allo: std.mem.Allocator, maxz: usize) ![]u8 { var msg: std.ArrayList(u8) = .empty; errdefer msg.deinit(allo); const rd = &self.rdr.interface; while (true) { const b0 = rd.takeByte() catch return self.fail(); const b1 = rd.takeByte() catch return self.fail(); const fin = (b0 & 0x80) != 0; const opc = b0 & 0x0f; const msk = (b1 & 0x80) != 0; var lenz: u64 = b1 & 0x7f; if (lenz == 126) { const two = rd.take(2) catch return self.fail(); lenz = mem.readInt(u16, two[0..2], .big); } else if (lenz == 127) { const eig = rd.take(8) catch return self.fail(); lenz = mem.readInt(u64, eig[0..8], .big); } if (lenz > maxz or msg.items.len + lenz > maxz) return error.TooBig; var key: [4]u8 = .{ 0, 0, 0, 0 }; if (msk) { const kb = rd.take(4) catch return self.fail(); @memcpy(&key, kb[0..4]); } const beg = msg.items.len; try msg.resize(allo, beg + @as(usize, @intCast(lenz))); rd.readSliceAll(msg.items[beg..]) catch return self.fail(); if (msk) { for (msg.items[beg..], 0..) |*byt, idx| { byt.* ^= key[idx % 4]; } }
switch (opc) { 0, 1, 2 => { if (fin) return msg.toOwnedSlice(allo); }, 8 => return error.Closed, 9 => { const pay = try allo.dupe(u8, msg.items[beg..]); defer allo.free(pay); msg.shrinkRetainingCapacity(beg); try self.sendRaw(0xA, pay); }, 10 => msg.shrinkRetainingCapacity(beg), else => return error.BadFrame } } }
fn evKeep(self: *Conn, msg: []u8) !void { if (self.evts.items.len >= CF.evmx or self.evby + msg.len > CF.evby) { self.gpaz.free(msg); self.evdr += 1; return; } self.evby += msg.len; try self.evts.append(self.gpaz, msg); }
pub fn call(self: *Conn, allo: std.mem.Allocator, method: []const u8, params: []const u8, mill: u32) ![]u8 { const idz = self.nid; self.nid += 1; const req = try std.fmt.allocPrint(allo, "{{\"id\":{d},\"method\":\"{s}\",\"params\":{s}}}", .{ idz, method, if (params.len == 0) "{}" else params }); defer allo.free(req); self.armz(mill); defer self.armz(0); try self.sendRaw(1, req); var pre: [32]u8 = undefined; const head = std.fmt.bufPrint(&pre, "{{\"id\":{d},", .{idz}) catch unreachable; while (true) { const msg = try self.readMsg(self.gpaz, CF.maxm); if (mem.startsWith(u8, msg, head)) { defer self.gpaz.free(msg); return allo.dupe(u8, msg); } if (mem.startsWith(u8, msg, "{\"method\"")) { try self.evKeep(msg); } else self.gpaz.free(msg); } }
pub fn callJson(self: *Conn, aren: std.mem.Allocator, method: []const u8, params: []const u8, mill: u32) !std.json.Value { const msg = try self.call(aren, method, params, mill); const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, msg, .{ .allocate = .alloc_always }) catch return error.CdpError; if (valu != .object) return error.CdpError; if (valu.object.get("error") != null) return error.CdpError; return valu.object.get("result") orelse .null; }
pub fn evWait(self: *Conn, aren: std.mem.Allocator, method: []const u8, from: *usize, mill: u32) !?[]const u8 { var pat: [96]u8 = undefined; const need = std.fmt.bufPrint(&pat, "\"method\":\"{s}\"", .{method}) catch return null; const deadl = nowMs(self.iozz) + mill; while (true) { while (from.* < self.evts.items.len) { const msg = self.evts.items[from.*]; from.* += 1; if (mem.find(u8, msg[0..@min(msg.len, 160)], need) != null) return try aren.dupe(u8, msg); } const left = deadl - nowMs(self.iozz); if (left <= 0) return null; self.armz(@intCast(left)); defer self.armz(0); const msg = self.readMsg(self.gpaz, CF.maxm) catch |err| { if (err == error.Timeout) return null; return err; }; if (mem.startsWith(u8, msg, "{\"method\"")) { try self.evKeep(msg); } else self.gpaz.free(msg); } }
pub fn close(self: *Conn) void { self.stop.store(true, .release); self.strm.shutdown(self.iozz, .both) catch {}; if (self.thrd) |thr| thr.join(); for (self.evts.items) |msg| self.gpaz.free(msg); self.evts.deinit(self.gpaz); self.strm.close(self.iozz); self.gpaz.free(self.rbuf); self.gpaz.free(self.wbuf); const gpaz = self.gpaz; gpaz.destroy(self); } };
pub fn nowMs(iozz: std.Io) i64 { return @intCast(std.Io.Clock.awake.now(iozz).toMilliseconds()); }
fn dogz(self: *Conn) void { while (!self.stop.load(.acquire)) { std.Io.sleep(self.iozz, .fromMilliseconds(CF.tick), .awake) catch {}; const dlz = self.dead.load(.acquire); if (dlz != 0 and nowMs(self.iozz) > dlz) { self.tout.store(true, .release); self.strm.shutdown(self.iozz, .both) catch {}; self.dead.store(0, .release); } } }
pub fn connect(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, path: []const u8, mill: u32) !*Conn { var addr = try net.IpAddress.parse("127.0.0.1", port); const strm = try addr.connect(iozz, .{ .mode = .stream }); errdefer strm.close(iozz); const rbuf = try gpaz.alloc(u8, CF.bufz); errdefer gpaz.free(rbuf); const wbuf = try gpaz.alloc(u8, CF.bufz); errdefer gpaz.free(wbuf); const self = try gpaz.create(Conn); errdefer gpaz.destroy(self); self.* = .{ .gpaz = gpaz, .iozz = iozz, .strm = strm, .rdr = strm.reader(iozz, rbuf), .wrt = strm.writer(iozz, wbuf), .rbuf = rbuf, .wbuf = wbuf }; self.thrd = try std.Thread.spawn(.{}, dogz, .{self}); errdefer { self.stop.store(true, .release); self.thrd.?.join(); }
var keyb: [16]u8 = undefined; iozz.random(&keyb); var k64: [24]u8 = undefined; _ = std.base64.standard.Encoder.encode(&k64, &keyb); const req = try std.fmt.allocPrint(gpaz, "GET {s} HTTP/1.1\r\nHost: 127.0.0.1:{d}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {s}\r\nSec-WebSocket-Version: 13\r\n\r\n", .{ path, port, &k64 }); defer gpaz.free(req); self.armz(mill); defer self.armz(0); self.wrt.interface.writeAll(req) catch return error.BadHandshake; self.wrt.interface.flush() catch return error.BadHandshake;
const rd = &self.rdr.interface; const first = rd.takeDelimiterInclusive('\n') catch return error.BadHandshake; if (mem.find(u8, first, " 101 ") == null) return error.BadHandshake; var acc: [28]u8 = undefined; var cat: [60]u8 = undefined; @memcpy(cat[0..24], &k64); @memcpy(cat[24..60], CF.guid); var dig: [20]u8 = undefined; std.crypto.hash.Sha1.hash(&cat, &dig, .{}); _ = std.base64.standard.Encoder.encode(&acc, &dig); var okay = false; while (true) { const line = rd.takeDelimiterInclusive('\n') catch return error.BadHandshake; if (line.len <= 2) break; if (std.ascii.startsWithIgnoreCase(line, "sec-websocket-accept:")) { if (mem.eql(u8, mem.trim(u8, line[21..], " \r\n"), &acc)) okay = true; } } if (!okay) return error.BadHandshake; return self; }
